// GitHub on the person's own login, a token they paste or a sign-in through our OAuth app: every operation of GitHub's
// REST API. actions.json is generated by `bun scripts/openapi-actions.ts github`. Plain git uses the same login (git-proxy.ts).
import { basename } from "node:path";
import { z } from "zod";
import { AppFile, AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, triggers, unwatch, watch } from "./triggers";

const api: Api = {
  name: "GitHub",
  base: "https://api.github.com",
  tokenHelp: "github.com/settings/tokens",
  auth: (key) => ({ Authorization: `Bearer ${key}`, Accept: "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "Emplio" }),
};

// what a sign-in asks for: code, pull requests and workflows, the person's organisations and gists
const SCOPES = "repo workflow read:org gist read:user user:email";

const raw: Api = { ...api, auth: (key, input) => ({ ...api.auth!(key, input), Accept: "application/vnd.github.raw" }) };

export const github: OwnApp = {
  app: "github",
  name: "GitHub",
  logo: "/logos/github.svg",
  keyField: {
    label: "Personal access token",
    help: "github.com/settings/tokens → Generate new token. Tick repo and workflow, or pick the repositories on a fine-grained token.",
    placeholder: "ghp_...",
  },
  async check(key) {
    const me = (await call(api, key, { method: "GET", path: "/user", query: [], headers: [] }, {})) as { login: string };
    return me.login;
  },
  // only on a server with our OAuth app's client id and secret; without them, tokens only
  oauth: {
    ready: () => Boolean(process.env.GITHUB_CLIENT_ID && process.env.GITHUB_CLIENT_SECRET),
    // select_account: always a screen to confirm on, so a sign-in link someone was sent can't finish by itself
    authorizeUrl: (redirect, state) =>
      `https://github.com/login/oauth/authorize?${new URLSearchParams({ client_id: process.env.GITHUB_CLIENT_ID!, redirect_uri: redirect, scope: SCOPES, state, prompt: "select_account" })}`,
    async exchange(code, redirect) {
      const res = await fetch("https://github.com/login/oauth/access_token", {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ client_id: process.env.GITHUB_CLIENT_ID, client_secret: process.env.GITHUB_CLIENT_SECRET, code, redirect_uri: redirect }),
        signal: AbortSignal.timeout(30_000),
      });
      const out = (await res.json().catch(() => null)) as { access_token?: string; error_description?: string } | null;
      if (!out?.access_token) throw new AppsError(out?.error_description ?? "GitHub didn't finish the sign-in. Try again.");
      return out.access_token;
    },
  },
  push: {
    events,
    triggers,
    start: (key, connection, event, config) => watch(api, key, connection, event, config),
    stop: (key, id) => unwatch(api, key, id),
  },
  actions: {
    ...(await specActions(new URL("./actions.json", import.meta.url), api)),
    get_raw_repository_content: {
      description: "Get one file from a repository as a file on the computer. For a whole repository, git clone it instead.",
      readOnly: true,
      input: z.object({
        owner: z.string(),
        repo: z.string(),
        path: z.string().describe("The file's path in the repository"),
        ref: z.string().optional().describe("Branch, tag or commit; the default branch if left out"),
      }),
      run: async (input: { path: string }, key: string) => {
        const got = await call(raw, key, { method: "GET", path: "/repos/{owner}/{repo}/contents/{path}", query: ["ref"], headers: [] }, input);
        return got instanceof AppFile ? new AppFile(basename(input.path), "application/octet-stream", got.bytes) : got;
      },
    },
  },
};
